 void LateUpdate(){long t=System.Diagnostics.Stopwatch.GetTimestamp();try{RefreshView();}finally{LastUpdateMicroseconds=(System.Diagnostics.Stopwatch.GetTimestamp()-t)*1000000.0/System.Diagnostics.Stopwatch.Frequency;}}
 void RefreshView(){if(root==null)return;RefreshBindingLabels();if(GameEntry.Loading){play.SetActive(false);details.SetActive(false);notifications.SetActive(false);return;}var k=Keyboard.current;if(k!=null){if(!PlayerInput.UIBlocked&&k.f2Key.wasPressedThisFrame&&Detail!="")SetUiScale(UiScale<1.1f?1.25f:UiScale<1.4f?1.5f:1);if(!PlayerInput.UIBlocked&&k.f3Key.wasPressedThisFrame)SetDetails("诊断");if(!PlayerInput.UIBlocked&&k.escapeKey.wasPressedThisFrame&&Detail!="")SetDetails("");}
  if(PlayerInput.Down(PlayerAction.Help))SetDetails("帮助");if(PlayerInput.Down(PlayerAction.Route))SetDetails("路线");
  if(Detail!=""&&(hero.Inventory.IsOpen||hero.SaveMenuOpen||hero.Progression.IsChoosing))SetDetails("");
  bool gameplay=!GameEntry.Loading&&(s.Flow.ActiveRun!=null||s.Flow.AtCamp&&s.Camp.Exploring)&&!s.Flow.HasResult&&!hero.SaveMenuOpen&&!hero.Inventory.IsOpen&&!hero.Progression.IsChoosing&&!s.Flow.Frozen;
  // A save failure is persistent and separate from ordinary notifications, including camp.
  CriticalMessage=!string.IsNullOrEmpty(s.Flow.Error)?s.Flow.Error:s.Saves.SaveFailed?s.Saves.FailureDetail:"";
  play.SetActive(gameplay&&Detail=="");
  if(Detail!=""&&Time.unscaledTime>=nextDetails){nextDetails=Time.unscaledTime+.25f;DrawDetails();}
  if(!play.activeSelf)return;
  Label(health,$"{hero.Health.Current:0} / {hero.Health.maxHealth:0}");Label(level,"等级"+hero.Progression.Level);hp.fillAmount=hero.Health.Current/hero.Health.maxHealth;xp.fillAmount=(float)hero.Progression.Experience/hero.Progression.RequiredExperience;
  if(Time.unscaledTime>=nextTarget){nextTarget=Time.unscaledTime+.3f;bool teaching=Onboarding.Active(s)&&(s.Flow.AtCamp||s.Flow.ActiveRun?.mode==AdventureMode.ForestExploration),tracked=CraftingTargets.Valid(s.Flow.Profile?.craftingTarget);targetPanel.SetActive(true);string icon="route";if(teaching){Label(targetText,Onboarding.HudText(s));icon=Onboarding.Icon(s);}else if(tracked){Label(targetText,CraftingTargets.Compact(s));var t=s.Flow.Profile.craftingTarget;icon=string.IsNullOrEmpty(t.containerId)?AdventureItems.Icon(t.type):AdventureCatalog.Item(t.containerId).iconKey;}else Label(targetText,s.Flow.AtCamp?"营地整备\n选择装备后出征":"自由探索\n可随时前往免费出口");targetIcon.sprite=icons.Get(icon);targetIcon.enabled=targetIcon.sprite!=null;Label(targetDetails.GetComponentInChildren<Text>(),teaching?"教学详情":"目标详情");Label(targetCancel.GetComponentInChildren<Text>(),teaching?"跳过引导":tracked?"取消目标":"查看教程");}
  Label(region,s.Flow.AtCamp?"营地 · 安全整备":s.Flow.ActiveRun.mode==AdventureMode.ForestExploration?"森林 · 开发中":$"第{s.Wave}波 · 剩余{s.enemies.Count(e=>!e.Health.Dead)}");
  RefreshFacilities();
  SlotState(main,gear.Main?.Icon,"主武器",combat.AttackRemaining,combat.BasicInterval);SlotState(reserve,gear.Reserve?.Icon,"切换",combat.SwitchRemaining,.7f,gear.Reserve!=null,gear.Reserve==null?"未配置":"");
  SlotState(skill,"skill_"+gear.Weapon.ToString().ToLowerInvariant(),combat.SkillName,combat.SkillRemaining,combat.SkillDuration);SlotState(roll,"dodge","翻滚",hero.Dodge.CooldownRemaining,Mathf.Max(hero.Dodge.duration,hero.Dodge.cooldown));SlotState(potion,"potion","药水",hero.Inventory.PotionCooldownRemaining,hero.Inventory.PotionCooldown,hero.Inventory.PotionOnQuickbar&&hero.Inventory.HealthPotionCount>0,hero.Inventory.PotionOnQuickbar?hero.Inventory.HealthPotionCount.ToString():"未配置");SlotState(supply,"supply","补给",0,1,true,s.Flow.SupplyUsed()+"/"+s.Flow.SupplyLimit);
  resolver.EnsureFresh();resolver.Present();VisibleEId=resolver.DisplayedE?.targetId;VisibleHId=resolver.DisplayedH?.targetId;
  var a=resolver.DisplayedE;var b=resolver.DisplayedH;bool extracting=s.Flow.ActiveRun?.phase==RunPhase.Extracting;
  context.SetActive(a!=null||b!=null||extracting);progress.enabled=extracting;context.transform.Find("ExtractionProgressBackground").gameObject.SetActive(extracting);
  if(extracting){float remaining=s.Flow.ActiveRun.extractionRemaining;var x=s.Flow.ExitConfigs().FirstOrDefault(e=>e.id==s.Flow.ActiveRun.exitId);progress.fillAmount=1-remaining/Mathf.Max(.1f,x?.duration??s.Flow.extractionDuration);Label(prompt,$"撤离中   {remaining:0.0} 秒");Label(secondary,a!=null&&a.Signature!=b?.Signature?OfferText(a,PlayerInput.Key(PlayerAction.Interact))+"\n["+PlayerInput.Key(PlayerAction.Exit)+"] 取消撤离":"["+(a!=null?PlayerInput.Pair:PlayerInput.Key(PlayerAction.Exit))+"] 取消 · 受击或离开会中断");contextIcon.sprite=icons.Get("exit");}
  else{bool same=a!=null&&b!=null&&a.Signature==b.Signature;Label(prompt,OfferText(a??b,same?PlayerInput.Pair:a!=null?PlayerInput.Key(PlayerAction.Interact):PlayerInput.Key(PlayerAction.Exit)));Label(secondary,!same&&a!=null&&b!=null?OfferText(b,PlayerInput.Key(PlayerAction.Exit)):"");contextIcon.sprite=icons.Get((a??b)?.icon);}
  bool compact=UiScale>1.01f;float width=compact?300:600;
  var cr=context.GetComponent<RectTransform>();cr.anchorMin=cr.anchorMax=new Vector2(compact?0:.5f,0);cr.pivot=new Vector2(compact?0:.5f,0);cr.anchoredPosition=new Vector2(compact?20:0,126);
