  notice.rectTransform.sizeDelta=new Vector2(compact?244:448,compact?70:44);notificationIcon.sprite=icons.Get(CriticalMessage!=""?"error":hero.Inventory.Notifications.IconKey);notificationIcon.enabled=notificationIcon.sprite!=null;notifications.transform.GetChild(1).GetComponent<RectTransform>().anchoredPosition=new Vector2(compact?12:498,compact?-80:-9);
  Label(saveText,s.Saves.SaveFailed?"保存失败 · 请重试":Time.unscaledTime-s.Saves.LastSavedAt<2?"已保存":"");saveIcon.sprite=icons.Get(s.Saves.SaveFailed?"error":"save");saveIcon.enabled=!string.IsNullOrEmpty(saveText.text);
 }
 string OfferText(InteractionOffer offer,string key){if(offer==null)return "";string line="["+key+"] "+offer.title;if(offer.action==InteractionAction.Repair)line+="\n"+offer.Cost+(offer.executable?" · 仅本局有效":offer.heldWood<offer.wood||offer.heldStone<offer.stone?" · 缺材料":" · "+offer.reason);else if(!offer.executable)line+=" · "+offer.reason;return line;}
 void RefreshBindingLabels(){if(inputRevision==PlayerInput.Revision||main==null)return;inputRevision=PlayerInput.Revision;s.GetComponent<OnboardingFocus>()?.Refresh();Label(main.key,PlayerInput.Cap(PlayerAction.Attack));Label(reserve.key,PlayerInput.Cap(PlayerAction.SwitchWeapon));Label(skill.key,PlayerInput.Cap(PlayerAction.Skill));Label(roll.key,PlayerInput.Cap(PlayerAction.Dodge));Label(potion.key,PlayerInput.Cap(PlayerAction.Potion));Label(supply.key,PlayerInput.Cap(PlayerAction.Items));Label(routeButton.GetComponentInChildren<Text>(),PlayerInput.Key(PlayerAction.Route)+" 路线");Label(helpButton.GetComponentInChildren<Text>(),PlayerInput.Key(PlayerAction.Help)+" 帮助");nextDetails=nextTarget=0;}
 void DrawDetails(){string value="";if(Detail=="帮助")value="当前武器："+combat.ClassName+"\n普攻："+combat.BasicDescription+"\n"+combat.SkillName+"："+combat.SkillDescription+"\n\n操作与规则\n"+PlayerInput.HelpText+"\n渡口先修复，再引导撤离；费用仅本局有效。\n退出保存检查点；失败丢本局战利品，已用材料不恢复。\n镜头前角色淡化，攻击与碰撞不变。\n操作/键位按钮可调整，F2 UI大小 "+(UiScale*100).ToString("0")+"%";
  else if(Detail=="教程")value=Onboarding.Details(s);
  else if(Detail=="路线"){var layout=GetComponent<ForestRegionRuntime>()?.Layout;value="森林测试 · 地点收益与路线\n"+(layout==null?"当前为波次测试。":string.Join("\n",layout.points.Select(p=>p.label+" · "+(layout.revision>=3?ForestRewards.Summary(p.siteKind):"旧版收益配置")))+"\n规划连接（可离路探索，实际通行以导航为准）："+string.Join(" · ",layout.routes.Select(e=>layout.points.First(p=>p.id==e.from).label+"↔"+layout.points.First(p=>p.id==e.to).label))+"\n\n"+CraftingTargets.Recommendations(s))+"\n普通出口免费；林地西侧渡口木2石1。";}
  else if(Detail=="目标")value=CraftingTargets.Details(s)+"\n\n森林讨伐记录\n"+ForestBossRules.Summary(s.Flow.Profile);
  else if(Detail=="诊断"){var run=s.Flow.ActiveRun;value="开发诊断（默认关闭）\nRun "+run?.runId+"\n区域 "+run?.regionInstanceId+"\n种子 "+run?.seed+" 内容 "+run?.contentRevision+"\n检查点 "+s.Flow.Revision+" 坐标 "+hero.transform.position+"\n带入 "+string.Join(",",run?.broughtRemaining??new int[0])+"\n本局 "+string.Join(",",run?.earnedRemaining??new int[0])+"\n恢复不保留飞行弹体/攻击前摇；正式版无诊断入口。";}
  inputButton.gameObject.SetActive(Detail=="帮助");tutorialControl.gameObject.SetActive(Detail=="教程");Label(tutorialControl.GetComponentInChildren<Text>(),Onboarding.Active(s)?"跳过引导":"启用（营地）");tutorialControl.interactable=Onboarding.Ready(s)&&(Onboarding.Active(s)||s.Flow.AtCamp);Label(detailCritical,CriticalMessage);Label(detailText,(CriticalMessage!=""?"保存受阻\n"+CriticalMessage+"\n\n":"")+value);
 }
 void RefreshFacilities(){FacilityRects.Clear();foreach(var t in facilityPanels)t.gameObject.SetActive(false);bool camp=s.Flow.AtCamp&&s.Camp.Exploring;var focus=s.GetComponent<OnboardingFocus>();if(!camp&&(!Onboarding.Active(s)||focus==null||!focus.Reachable||focus.CapturedStage!=Onboarding.State(s).stage))return;float unit=scaler.referenceResolution.y/Screen.height;float w=Screen.width*unit,h=Screen.height*unit;var used=new List<Rect>();
  foreach(var g in groups){if(!g.gameObject.activeInHierarchy)continue;var c=new Vector3[4];g.GetWorldCorners(c);used.Add(new Rect(c[0].x*unit,(Screen.height-c[1].y)*unit,(c[2].x-c[0].x)*unit,(c[1].y-c[0].y)*unit));}
  for(int i=0;i<(camp?4:1);i++){var world=camp?s.Camp.FacilityPosition(CampRuntime.FacilityIds[i]):focus.Position;var p=s.orbit.GetComponent<Camera>().WorldToScreenPoint(world+Vector3.up*1.8f);bool behind=p.z<=0;if(behind&&camp)continue;if(behind){p.x=Screen.width*.5f;p.y=Screen.height*.5f;}Rect r=default;bool placed=false;for(int j=0;j<160&&!placed;j++){int column=j%5;float dx=column==0?0:column%2==1?(column+1)/2:-(column/2);int row=j/5;float dy=row==0?0:row%2==1?(row+1)/2:-(row/2);r=new Rect(Mathf.Clamp(p.x*unit-90+dx*185,12,w-192),Mathf.Clamp((Screen.height-p.y)*unit+dy*44,12,h-164),180,42);placed=!used.Any(a=>a.Overlaps(r));}if(!placed)continue;used.Add(r);var t=facilityLabels[i];facilityPanels[i].gameObject.SetActive(true);facilityPanels[i].anchoredPosition=new Vector2(r.x,-r.y);bool current=!camp||Onboarding.Active(s)&&Onboarding.FacilityId(s)==CampRuntime.FacilityIds[i];string label=camp?(current?"当前 · ":"")+CampRuntime.FacilityNames[i]+"\n"+Vector3.Distance(hero.transform.position,world).ToString("0")+"米":focus.Hint+"\n"+(behind?"目标在身后 · 转动视角":"当前教学地点");Label(t,label);t.color=current?gold:ink;FacilityRects.Add(new Rect(r.x/unit,r.y/unit,r.width/unit,r.height/unit));}
 }
 void OnDestroy(){if(hero!=null&&Detail!="")SetDetails("");icons?.Dispose();if(flatSprite!=null)Destroy(flatSprite);if(font!=null)Destroy(font);if(root!=null)Destroy(root);if(Instance==this)Instance=null;}
